const SECRET_HEADER = 'x-n8n-webhook-secret'

function readHeader(headers, name) {
  if (!headers || typeof headers !== 'object') return undefined
  const target = name.toLowerCase()
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === target) {
      const value = headers[key]
      return Array.isArray(value) ? value[0] : value
    }
  }
  return undefined
}

function decimalCents(value, name) {
  if (typeof value !== 'string') throw new Error(name + ' must be a decimal string')
  const match = /^(-?)(0|[1-9]\d*)(?:\.(\d{1,2}))?$/.exec(value.trim())
  if (!match) throw new Error(name + ' must be a valid amount with at most two decimal places')
  const cents = BigInt(match[2]) * 100n + BigInt((match[3] || '').padEnd(2, '0') || '0')
  return match[1] ? -cents : cents
}

const configuredSecret = $env.N8N_WEBHOOK_SECRET
const item = $input.first().json
const suppliedSecret = readHeader(item.headers || {}, SECRET_HEADER)
if (!configuredSecret) throw new Error('N8N_WEBHOOK_SECRET is not configured')
if (!suppliedSecret || suppliedSecret !== configuredSecret) throw new Error('Invalid or missing webhook secret')

const body = item.body && typeof item.body === 'object' ? item.body : item
const dispute = body.dispute
const idempotencyKey = typeof body.idempotencyKey === 'string' ? body.idempotencyKey.trim() : ''
if (body.deliveryMode !== 'automatic') throw new Error('deliveryMode must be automatic')
if (!idempotencyKey) throw new Error('idempotencyKey is required')
if (!dispute || typeof dispute !== 'object') throw new Error('dispute payload is required')

const recipient = typeof dispute.recipient === 'string' ? dispute.recipient.trim() : ''
const subject = typeof dispute.subject === 'string' ? dispute.subject.trim() : ''
const message = typeof dispute.body === 'string' ? dispute.body.trim() : ''
const disputeId = dispute.id
if (!Number.isSafeInteger(disputeId) || disputeId <= 0) throw new Error('dispute.id must be a positive integer')
if (idempotencyKey !== 'dispute-' + disputeId) throw new Error('idempotencyKey must match dispute.id')
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipient)) throw new Error('dispute.recipient must be a valid email address')
if (!subject || subject.length > 255) throw new Error('dispute.subject is required and must be 255 characters or fewer')
if (!message || message.length > 20000) throw new Error('dispute.body is required and must be 20,000 characters or fewer')
for (const field of ['artistName', 'platform', 'trackName', 'statementPeriod']) {
  if (typeof dispute[field] !== 'string' || !dispute[field].trim()) throw new Error('dispute.' + field + ' is required')
}

const audit = dispute.audit
if (!audit || typeof audit !== 'object' || !Number.isSafeInteger(audit.discrepancyId) || audit.discrepancyId <= 0) {
  throw new Error('dispute.audit with discrepancyId is required')
}
if (audit.discrepancyStatus !== 'open') throw new Error('dispute discrepancy must be open')
const expected = decimalCents(audit.expectedAmount, 'expectedAmount')
const actual = decimalCents(audit.actualAmount, 'actualAmount')
const difference = decimalCents(audit.difference, 'difference')
const threshold = decimalCents(audit.threshold, 'threshold')
if (expected <= actual || expected - actual !== difference || difference <= threshold) {
  throw new Error('dispute does not meet the recorded underpayment threshold')
}

const staticData = $getWorkflowStaticData('global')
if (!staticData.sentReceipts || typeof staticData.sentReceipts !== 'object') staticData.sentReceipts = {}
const existing = staticData.sentReceipts[idempotencyKey]
if (existing) return [{ json: Object.assign({}, existing, { idempotentReplay: true }) }]
return [{ json: { idempotencyKey, disputeId, recipient, subject, message, idempotentReplay: false } }]
